def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_def = 0
    me_def = 0
    for a in opp:
        if a == 'D':
            opp_def += 1
    for a in me:
        if a == 'D':
            me_def += 1

    last_me = history[-1][0]
    last_opp = history[-1][1]

    # Strong endgame exploitation: if opponent is not a pure punisher, take value.
    if n >= 96:
        recent6 = opp[-6:]
        r6d = 0
        for a in recent6:
            if a == 'D':
                r6d += 1
        if opp_def * 4 >= n * 3:
            return 'D'
        if r6d >= 5:
            return 'D'
        if n >= 99:
            return 'D'
        if n >= 97 and last_opp == 'C':
            return 'D'
        return 'C'

    # Detect pure / near-pure cooperator: exploit heavily but retain a tiny
    # hedge in case of a hidden retaliatory trigger.
    if opp_def == 0:
        if n >= 6:
            if rng.random() < 0.88:
                return 'D'
            return 'C'
        return 'C'

    # Detect pure / near-pure defector.
    if opp_def >= n - 1 and n >= 4:
        return 'D'

    # Recent windows.
    w = 8 if n >= 8 else n
    recent = opp[-w:]
    rd = 0
    for a in recent:
        if a == 'D':
            rd += 1
    rc = w - rd

    # Opponent is heavily defecting overall.
    if opp_def * 2 > n:
        # Watch for a possible late conversion to cooperation.
        if n >= 12:
            tail8 = opp[-8:]
            td = 0
            for a in tail8:
                if a == 'D':
                    td += 1
            if td <= 2 and last_opp == 'C':
                # They've calmed down; try to rebuild with limited risk.
                if rng.random() < 0.55:
                    return 'C'
                return 'D'
        # If they just cooperated after a long defection streak, test forgiveness.
        if last_opp == 'C' and rd >= 3:
            if rng.random() < 0.4:
                return 'C'
            return 'D'
        return 'D'

    # Opponent behaves like a retaliator / tit-for-tat.
    # Estimate whether opponent mimics our previous action.
    if n >= 6:
        mimic = 0
        denom = n - 1
        for i in range(1, n):
            if history[i][1] == history[i - 1][0]:
                mimic += 1
        if mimic * 10 >= denom * 6:
            # Generous tit-for-tat against a retaliator.
            if last_opp == 'D':
                # If our previous move was D, likely retaliation: return C.
                if last_me == 'D':
                    return 'C'
                # If they defected after we cooperated, punish once then forgive.
                if n >= 2 and history[-2][1] == 'D' and history[-2][0] == 'D':
                    return 'D'
                return 'D' if rng.random() < 0.6 else 'C'
            return 'C'

    # Opponent is moderately cooperative.
    if last_opp == 'C':
        # If they've cooperated a lot and we've been mostly cooperative, keep it.
        if opp_def * 5 <= n:
            # Rare controlled probe in the middle if mutual cooperation is long.
            if n >= 25 and me_def == 0 and opp_def == 0:
                if rng.random() < 0.03:
                    return 'D'
                return 'C'
            return 'C'
        # Otherwise cooperate, with occasional opportunistic defection.
        if rc >= 5 and rng.random() < 0.18:
            return 'D'
        return 'C'

    # last_opp == 'D'
    if rd >= 4:
        return 'D'
    if opp_def * 3 > n:
        # Stingy forgiveness for persistent defectors.
        if last_me == 'D' and rng.random() < 0.2:
            return 'C'
        return 'D'
    # Moderate defection: punish once, then usually cooperate.
    if n >= 4:
        prev_me = history[-2][0]
        prev_opp = history[-2][1]
        if prev_opp == 'D' and last_opp == 'D' and prev_me == 'D':
            # mutual retaliation loop; break it more often.
            if rng.random() < 0.45:
                return 'C'
            return 'D'
    if rng.random() < 0.3:
        return 'C'
    return 'D'
